from __future__ import annotations

from collections.abc import Callable
from typing import Any

import streamlit as st

from optichub.grpc_client import ModuleInfo, configure_module, start_module, stop_module


def tab_redis_queue_worker(
    host: str,
    port: int,
    info: ModuleInfo | None,
    cfg: dict[str, Any],
    running: bool,
    can_stop: bool,
    key: Callable[[str], str],
) -> None:
    queue_name = st.text_input(
        "Queue name",
        value=str(cfg.get("queue_name", "")),
        key=key("m_rq_queue"),
    )
    num_workers = st.number_input(
        "Number of workers",
        min_value=1,
        value=int(cfg.get("num_workers", 1)),
        step=1,
        key=key("m_rq_nw"),
    )
    payload = {
        "queue_name": queue_name.strip(),
        "num_workers": int(num_workers),
    }

    c1, c2 = st.columns(2)
    with c1:
        if st.button("Start", type="primary", disabled=running, key=key("m_rq_start")):
            ok, msg = start_module(host, port, module="redis_queue_worker", config=payload)
            if ok:
                st.success(msg or "started")
                st.rerun()
            else:
                st.error(msg)
    with c2:
        if st.button("Stop", disabled=not can_stop, key=key("m_rq_stop")):
            ok, msg = stop_module(host, port, module="redis_queue_worker")
            if ok:
                st.success(msg or "stopped")
                st.rerun()
            else:
                st.error(msg)

    if st.button("Apply config (restart module)", disabled=not running, key=key("m_rq_apply")):
        ok, msg = configure_module(host, port, module="redis_queue_worker", config=payload)
        if ok:
            st.success(msg or "reconfigured")
            st.rerun()
        else:
            st.error(msg)


def tab_redis_queue_burst_worker(
    host: str,
    port: int,
    info: ModuleInfo | None,
    cfg: dict[str, Any],
    running: bool,
    can_stop: bool,
    key: Callable[[str], str],
) -> None:
    st.caption(
        "Same settings as the long-running Redis queue worker, but runs **`rq worker --burst`**. "
        "When every burst worker process has exited, the module stops and clears the saved "
        "**enabled** flag (same as pressing Stop)."
    )
    queue_name = st.text_input(
        "Queue name",
        value=str(cfg.get("queue_name", "")),
        key=key("m_rqb_queue"),
    )
    num_workers = st.number_input(
        "Number of workers",
        min_value=1,
        value=int(cfg.get("num_workers", 1)),
        step=1,
        key=key("m_rqb_nw"),
    )
    payload = {
        "queue_name": queue_name.strip(),
        "num_workers": int(num_workers),
    }

    c1, c2 = st.columns(2)
    with c1:
        if st.button("Start burst", type="primary", disabled=running, key=key("m_rqb_start")):
            ok, msg = start_module(host, port, module="redis_queue_burst_worker", config=payload)
            if ok:
                st.success(msg or "started")
                st.rerun()
            else:
                st.error(msg)
    with c2:
        if st.button("Stop", disabled=not can_stop, key=key("m_rqb_stop")):
            ok, msg = stop_module(host, port, module="redis_queue_burst_worker")
            if ok:
                st.success(msg or "stopped")
                st.rerun()
            else:
                st.error(msg)

    if st.button("Apply config (restart module)", disabled=not running, key=key("m_rqb_apply")):
        ok, msg = configure_module(host, port, module="redis_queue_burst_worker", config=payload)
        if ok:
            st.success(msg or "reconfigured")
            st.rerun()
        else:
            st.error(msg)
